#!/usr/bin/env python3
"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):
    ws = _workspace(args)
    for name in ("state.json", "session.json"):
        p = ws / name
        if p.exists():
            p.unlink()
    _emit({"ok": True, "reset": True, "workspace": str(ws),
           "note": "session gates cleared; domain data is re-seeded per task from world.db"})


def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    # Persist multi-step session flags (policy-check / preview gates).
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))

    is_write = args.tool in WRITE_TOOL_NAMES
    _emit({"tool": args.tool, "is_write": is_write, "result": result})


def main():
    p = argparse.ArgumentParser(description="STATE-Bench portable domain skill CLI")
    sub = p.add_subparsers(dest="cmd", required=True)
    sub.add_parser("tools").set_defaults(fn=cmd_tools)
    pr = sub.add_parser("reset")
    pr.add_argument("--workspace", default=None)
    pr.set_defaults(fn=cmd_reset)
    pc = sub.add_parser("call")
    pc.add_argument("tool")
    pc.add_argument("--args", default="{}")
    pc.add_argument("--now", default=None)
    pc.add_argument("--workspace", default=None)
    pc.set_defaults(fn=cmd_call)
    a = p.parse_args()
    a.fn(a)


if __name__ == "__main__":
    main()

"""Tool schemas (OpenAI function calling format) for the customer support environment.

11 tools: 6 READ, 5 WRITE.
All WRITE tools are two-step (preview → confirm) and require prior get_policies call.
"""

from typing import Any

# ---------------------------------------------------------------------------
# READ tools
# ---------------------------------------------------------------------------

GET_ORDER: dict[str, Any] = {
    "type": "function",
    "name": "get_order",
    "description": (
        "Retrieve full details of an order by its order ID. "
        "Returns the order, all items in the order, and product details for each item."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "order_id": {"type": "string", "description": "The order ID (e.g. 'ORD-5001')"},
        },
        "required": ["order_id"],
    },
}

GET_CUSTOMER: dict[str, Any] = {
    "type": "function",
    "name": "get_customer",
    "description": (
        "Retrieve customer profile including membership tier, store credit balance, and preference settings."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "customer_id": {"type": "string", "description": "The customer ID (e.g. 'cust_001')"},
        },
        "required": ["customer_id"],
    },
}

SEARCH_PRODUCTS: dict[str, Any] = {
    "type": "function",
    "name": "search_products",
    "description": (
        "Search the task-local product catalog by free-text query. "
        "Returns ranked compact matches with product_id, name, matched_field, category, subcategory, and in_stock. "
        "Call get_product_details with a returned product_id for price, stock, warranty, and return-window details."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "query": {"type": "string", "description": "Free-text product search query, such as 'large shirt'"},
        },
        "required": ["query"],
    },
}

GET_PRODUCT_DETAILS: dict[str, Any] = {
    "type": "function",
    "name": "get_product_details",
    "description": (
        "Retrieve full product details by exact product ID, including current price, stock status, "
        "warranty terms, and return window. Use search_products first when you do not know the product ID."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "product_id": {"type": "string", "description": "The product ID (e.g. 'PROD-1001')"},
        },
        "required": ["product_id"],
    },
}

GET_POLICIES: dict[str, Any] = {
    "type": "function",
    "name": "get_policies",
    "description": (
        "Look up the company's policies for a given topic. "
        "IMPORTANT: You must call this before using any write tool (process_return, process_refund, "
        "cancel_order, process_exchange, process_warranty_claim). "
        "The system will reject write operations if the relevant policy has not been reviewed first."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "topic": {
                "type": "string",
                "enum": ["return", "refund", "cancellation", "exchange", "warranty", "shipping"],
                "description": "The policy topic to look up",
            },
        },
        "required": ["topic"],
    },
}

GET_WARRANTY_STATUS: dict[str, Any] = {
    "type": "function",
    "name": "get_warranty_status",
    "description": (
        "Check the warranty status for a specific item. Returns warranty type, "
        "coverage period, claim history, and current eligibility."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "item_id": {"type": "string", "description": "The order item ID (e.g. 'ITEM-8001')"},
        },
        "required": ["item_id"],
    },
}

# ---------------------------------------------------------------------------
# WRITE tools (all two-step: preview → confirm)
# ---------------------------------------------------------------------------

PROCESS_RETURN: dict[str, Any] = {
    "type": "function",
    "name": "process_return",
    "description": (
        "Process a return for an order item. Two-step operation: "
        "first call without confirm to preview the return (eligibility, fees, component breakdown), "
        "then call again with confirm=true AND amount=<computed net refund> to execute. "
        "On confirm, you must compute the net refund yourself from the preview's components "
        "(restocking_fee, restocking_discount, shipping_clawback, bulk_clawback, repeat_surcharge, "
        "paid_return_shipping_fee) and pass it as `amount`. The env writes whatever amount you submit. "
        "Requires prior call to get_policies(topic='return')."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "item_id": {"type": "string", "description": "The order item ID to return"},
            "reason": {
                "type": "string",
                "enum": [
                    "defective",
                    "wrong_item",
                    "not_as_described",
                    "changed_mind",
                    "damaged_in_transit",
                ],
                "description": "Reason for the return",
            },
            "amount": {
                "type": "integer",
                "description": (
                    "Net refund amount in dollars (required on confirm; ignored on preview). "
                    "Compute from the preview's component breakdown: base item price minus "
                    "restocking_fee plus restocking_discount minus shipping_clawback minus "
                    "bulk_clawback minus repeat_surcharge minus paid_return_shipping_fee. "
                    "The env writes this value verbatim to item.refund_amount; getting it wrong "
                    "is a scoring failure."
                ),
            },
            "confirm": {
                "type": "boolean",
                "description": "Set to true to execute the return after previewing. Omit or set false to preview only.",
            },
        },
        "required": ["item_id", "reason"],
    },
}

PROCESS_REFUND: dict[str, Any] = {
    "type": "function",
    "name": "process_refund",
    "description": (
        "Process a refund for an order item. Two-step operation: "
        "first call without confirm to preview the refund calculation, "
        "then call with confirm=true to execute. "
        "Requires prior call to get_policies(topic='refund')."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "item_id": {"type": "string", "description": "The order item ID to refund"},
            "refund_method": {
                "type": "string",
                "enum": ["original_payment", "store_credit"],
                "description": "How to issue the refund",
            },
            "amount": {
                "type": "integer",
                "description": "Refund amount in dollars. Must match the policy-computed amount.",
            },
            "confirm": {
                "type": "boolean",
                "description": "Set to true to execute the refund after previewing. Omit or set false to preview only.",
            },
        },
        "required": ["item_id", "refund_method", "amount"],
    },
}

CANCEL_ORDER: dict[str, Any] = {
    "type": "function",
    "name": "cancel_order",
    "description": (
        "Cancel an order or specific items within an order. Two-step operation: "
        "first call without confirm to preview cancellation (fees, refund), "
        "then call with confirm=true to execute. "
        "Pass item_ids to cancel specific items, or omit to cancel the entire order. "
        "Requires prior call to get_policies(topic='cancellation')."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "order_id": {"type": "string", "description": "The order ID to cancel"},
            "item_ids": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Specific item IDs to cancel. Omit to cancel entire order.",
            },
            "confirm": {
                "type": "boolean",
                "description": "Set to true to execute the cancellation after previewing.",
            },
        },
        "required": ["order_id"],
    },
}

PROCESS_EXCHANGE: dict[str, Any] = {
    "type": "function",
    "name": "process_exchange",
    "description": (
        "Exchange an item for a different product or variant. Two-step operation: "
        "first call without confirm to preview (price difference, eligibility), "
        "then call with confirm=true to execute. "
        "Requires prior call to get_policies(topic='exchange')."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "item_id": {"type": "string", "description": "The order item ID to exchange"},
            "new_product_id": {
                "type": "string",
                "description": "The product ID for the replacement item",
            },
            "confirm": {
                "type": "boolean",
                "description": "Set to true to execute the exchange after previewing.",
            },
        },
        "required": ["item_id", "new_product_id"],
    },
}

PROCESS_WARRANTY_CLAIM: dict[str, Any] = {
    "type": "function",
    "name": "process_warranty_claim",
    "description": (
        "File a warranty claim for a defective item. Two-step operation: "
        "first call without confirm to preview (eligibility, resolution type, cost), "
        "then call with confirm=true to execute. "
        "Only active items can receive warranty claims; do not call for items already returned, exchanged, or cancelled. "
        "Requires prior call to get_policies(topic='warranty')."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "warranty_id": {"type": "string", "description": "The warranty ID (e.g. 'WRT-3001')"},
            "item_id": {"type": "string", "description": "The order item ID with the defect"},
            "issue_description": {
                "type": "string",
                "description": "Description of the defect or issue",
            },
            "confirm": {
                "type": "boolean",
                "description": "Set to true to execute the warranty claim after previewing.",
            },
        },
        "required": ["warranty_id", "item_id", "issue_description"],
    },
}

# ---------------------------------------------------------------------------
# Aggregated list
# ---------------------------------------------------------------------------

TOOL_SCHEMAS: list[dict[str, Any]] = [
    # READ
    GET_ORDER,
    GET_CUSTOMER,
    SEARCH_PRODUCTS,
    GET_PRODUCT_DETAILS,
    GET_POLICIES,
    GET_WARRANTY_STATUS,
    # WRITE
    PROCESS_RETURN,
    PROCESS_REFUND,
    CANCEL_ORDER,
    PROCESS_EXCHANGE,
    PROCESS_WARRANTY_CLAIM,
]

WRITE_TOOL_NAMES: list[str] = [
    "process_return",
    "process_refund",
    "cancel_order",
    "process_exchange",
    "process_warranty_claim",
]

# E-commerce customer support — Policies

Full policy reference for this domain. The agent can also fetch any topic at
runtime via the `get_policies` tool. Topics below are the canonical set.

